import React,{useState,useEffect} from 'react';
import {useTheme,Alert,Box,Button,Dialog,DialogActions,DialogContent,DialogTitle,Checkbox,FormControlLabel,MenuItem,Paper,Radio,RadioGroup,Stack,Tab,Tabs,Table,TableBody,TableCell,TableContainer,TableHead,TableRow,TextField,Typography} from '@mui/material';
import {CardPages} from './participant-ui';
import {companySubmissionReason,recommendationReason,reflectionReason} from './submission-status';

function BrandMark({name,height=44}) {
  const theme=useTheme(),label={vfi:'VFI — technology supplier',fairpass:'FairPass — original verification technology',facepass:'FacePass — next-generation platform'}[name];
  return <Box component="img" src={`/brand/${name}${theme.palette.mode==='dark'?'-reverse':''}.svg`} alt={label} sx={{height:name==='fairpass'?Math.max(height,88):height,width:'auto',maxWidth:'100%',objectFit:'contain'}}/>;
}
const money=value=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(value*1000000);
function Paragraphs({text=''}) {
  return text.split('\n\n').map((paragraph,index)=><Typography key={index} sx={{maxWidth:'65ch',whiteSpace:'pre-line'}}>{paragraph.replace(/^#{1,6} /,'').replace(/\*\*/g,'')}</Typography>);
}
function Status({state,year=1}) {
  const values=[['Cash reserves',money(state.cash)],['Annual baseline revenue',money(state.annual_baseline_revenue)],['Reported annual revenue',money(state.reported_annual_revenue??state.annual_baseline_revenue)],['Outstanding VFI operating liability',money(state.vfi_operating_payable_m||0)],['Employees',state.employees],['Customer trust',`${state.customer_trust}/100`],['Workforce conditions',`${state.workforce_conditions}/100`],['Technical reliability',`${state.technical_reliability}/100`],['Sustainability',`${state.sustainability}/100`],['Partnership standing',`${state.partnership_standing}/100`],['Verification operational',state.vfi_operational?'Yes':'No'],['Northstar contract',state.northstar_contract||'None'],[state.identity_technology_provider==='independent_migrated'?'Annual VFI licensing fee':'Recorded annual verification cost',money(state.annual_vfi_cost)],['Contract revenue from Year 4',money(state.contract_revenue)]];
  if(state.platform_shift_applies)values.push(['Verification provider',({in_house:'Company-owned',vfi:'VFI',hybrid_vfi:'Hybrid using VFI',independent_migrated:'Independent after migration',none:'No identity verification'})[state.identity_technology_provider]||'Not recorded'],['VFI supplier contract',state.vfi_supplier_contract?'Yes':'No'],['Supplier dependence',state.supplier_dependence],['FacePass contract',state.facepass_contract||'None recorded'],['Supplier data-use terms',({none:'No VFI secondary-use claim',broad_proposed:'Broad contractual claims; authorization is separate',restricted:'Supplier secondary use restricted',contested:'Terms contested'})[state.supplier_data_rights]||'Not recorded'],['Biometric capability',state.biometric_capability],['AI training authorized',state.ai_training_authorized===true?'Yes':state.ai_training_authorized===false?'No':'Not recorded'],['Biometric secondary use authorized',state.biometric_secondary_use_authorized===true?'Yes':state.biometric_secondary_use_authorized===false?'No':'Not recorded'],['Biometric venue revenue from Year 9',state.biometric_venue_contract_active?money(state.biometric_venue_contract_value_m):'No active contract'],['Biometric provider',state.facial_entry_provider?.replaceAll('_',' ')||'None'],['Supplier obligations',[state.supplier_dispute_pending&&'Dispute',state.exemption_expiry_decision_required&&'Expired exemption: decision required',state.supplier_lock_in_crisis&&'Cannot afford to exit',state.verification_service_disruption&&'Verification disruption'].filter(Boolean).join('; ')||'None recorded']);
  if(year>=6)values.push(['Mandatory VFI',state.mandatory_vfi_active?'Yes':'No'],['Facial entry authorized',state.facial_entry_authorized?'Yes':'No'],['Facial entry operational',state.facial_entry_operational?'Yes':'No'],['Venue entry contract',state.biometric_venue_contract_active?'Biometric services: active from Year 9':state.entry_contract_active?'Nonbiometric services: active':state.entry_contract_pending?'Pending':'None'],['Available records',(state.available_data_categories||[]).map(s=>s.replaceAll('_',' ')).join(', ')]);
  return <Box component="dl" className="compact-ledger">{values.map(([label,value])=><React.Fragment key={label}><dt>{label}</dt><dd>{value}</dd></React.Fragment>)}</Box>;
}
function Record({company}) {
  return <Stack spacing={3}>{company.history.map(step=><Paper className="work-panel" variant="outlined" key={step.year}><Typography component="h2" variant="h6">Year {step.year}</Typography><Typography>{step.option_title||step.option} · {step.resolution_mode}</Typography>{step.annual_notice&&<Paragraphs text={step.annual_notice}/>}<Paragraphs text={step.outcome}/>{step.external_resolution&&<><Typography component="h3" variant="subtitle2">{step.external_resolution.title}</Typography><Paragraphs text={step.external_resolution.text}/></>}{step.modifiers?.map((text,index)=><Paragraphs key={index} text={text}/>)}{['external','internal'].map(kind=><Box key={kind}><Typography component="h3" variant="subtitle2">{kind==='external'?'External event':'Internal event'} · {step[kind].title}</Typography><Paragraphs text={step[kind].text}/>{step[kind].public_response&&<Paragraphs text={step[kind].public_response}/>}</Box>)}</Paper>)}</Stack>;
}
export function ProjectionVideo({src,title,onContinue,continueLabel}) {
 return <Stack spacing={3} className="class-screen"><Typography component="h1" variant="h4">{title}</Typography><Box component="video" controls playsInline preload="metadata" src={src} aria-label={title} sx={{width:'100%',maxHeight:'65dvh',objectFit:'contain'}}/><Box><Button variant="contained" onClick={onContinue}>{continueLabel}</Button></Box></Stack>;
}

function CompanyWelcome({introduction,onContinue,onReturn,onReturnRole}) {
 const sections=introduction.replace(/^#[^\n]*\n+/, '').split(/(?=^#{2,6}\s+)/m).filter(text=>text.trim()).map(text=>{
  const [heading,...body]=text.trim().split('\n');
  return {title:heading.replace(/^#{2,6}\s+/,''),body:body.join('\n').trim()};
 });
 return <Box className="welcome-intro"><Typography component="h1" variant="h4">Welcome to the European Live Entertainment Market</Typography><Box className="welcome-grid">{sections.map((section,index)=><Paper component="section" variant="outlined" className="welcome-card" key={section.title} aria-labelledby={`welcome-heading-${index}`}><Typography component="h2" variant="h6" id={`welcome-heading-${index}`}>{section.title}</Typography><Box className="welcome-card-copy" role="region" aria-labelledby={`welcome-heading-${index}`} tabIndex={0}><Stack spacing={1.5}><Paragraphs text={section.body}/></Stack></Box></Paper>)}</Box><Box className="welcome-continue inline-actions"><Button variant="contained" onClick={onContinue}>Continue to company setup</Button><Button variant="outlined" onClick={onReturn}>Return to a saved company</Button><Button variant="outlined" onClick={onReturnRole}>Return to my student role</Button></Box></Box>;
}

export function V4Home({api,sessionPath,go,sid,phone,setError}) {
  const [returning,setReturning]=useState(false);
  const [content,setContent]=useState(null),[read,setRead]=useState(phone),[name,setName]=useState(''),[country,setCountry]=useState(''),[code,setCode]=useState(sid||''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false);
  useEffect(()=>{api('/api/v4/content',undefined,'').then(setContent).catch(e=>setError(e.message));},[]);
  async function join(event) {
    event.preventDefault();setBusy(true);
    try {
      const session=await api(`${sessionPath(code)}/join`,{password},'');
      localStorage.setItem('fairpass-join:'+session.id,session.token);
      const company=await api(`${sessionPath(session.id)}/${phone?'locate':'companies'}`,{name,country,...(!phone&&returning?{resume_only:true}:{})},session.token);
      go(phone?'student':'company',session.id,company.id,company.token);
    } catch(error) {setError(error.message);setBusy(false);}
  }
  if(!content)return <Typography>Loading briefing…</Typography>;
  if(!read)return <CompanyWelcome introduction={content.introduction} onContinue={()=>{setReturning(false);setRead(true);}} onReturn={()=>{setReturning(true);setRead(true);}} onReturnRole={()=>{const u=new URL(location.href);u.searchParams.set('screen','student');u.hash='';location.href=u.href;}}/>;
  return <Stack spacing={3} component="form" onSubmit={join} sx={{maxWidth:'38rem',mx:'auto'}}><Typography component="h1" variant="h4">{phone?'Return or join your student role':returning?'Return to your company':'Company setup'}</Typography>{phone&&<Typography>Closed your QR window? Enter your company name, session code and password. Then choose your existing role and enter the same student name. Your submitted work will reopen.</Typography>}{!phone&&<Tabs value={returning?'return':'new'} onChange={(_,mode)=>setReturning(mode==='return')} aria-label="Company entry"><Tab value="new" label="New company"/><Tab value="return" label="Return to saved company"/></Tabs>}<TextField label="Company name" helperText={!phone?"Use the same name to reopen an existing company.":undefined} required value={name} onChange={e=>setName(e.target.value)} inputProps={{maxLength:60}}/>{!phone&&!returning&&<TextField select required label="EU headquarters" value={country} onChange={e=>setCountry(e.target.value)} helperText="Headquarters has no effect on simulation outcomes. Company name and headquarters are locked after confirmation.">{content.countries.map(c=><MenuItem key={c} value={c}>{c}</MenuItem>)}</TextField>}{!sid&&<TextField label="Session code" required value={code} onChange={e=>setCode(e.target.value.toUpperCase())}/>}<TextField label="Session password" required type="password" value={password} onChange={e=>setPassword(e.target.value)}/><Button type="submit" disabled={busy} variant="contained">{returning&&!phone?'Return to company':'Confirm and join'}</Button></Stack>;
}
export function V4Company({value,api,companyPath,setValue,setError,QR,phoneLink,ReportButtons,Timer}) {
  const [view,setView]=useState('team'),[choice,setChoice]=useState(''),[busy,setBusy]=useState(false),[externalSeen,setExternalSeen]=useState(false),[notice,setNotice]=useState(''),[localError,setLocalError]=useState('');
  const c=value.company,s=c.scenario,progress=c.progress,decision=c.decisions[String(c.year)];
  const submissionReason=companySubmissionReason({busy,started:c.started,choice,progress,options:s?.options,companyActive:c.active!==false});
  useEffect(()=>{setChoice('');if(c.started)setView(c.phase==='handoff'?'record':'brief');},[c.year,c.phase,c.started]);
  useEffect(()=>setExternalSeen(false),[c.year]);
  async function action(name) {
    if(value.read_only)return;
    setBusy(true);setLocalError('');setNotice('');
    try {const next=await api(`${companyPath()}/actions`,{action:name,option:choice,year:c.year,version:c.version});setValue(next);setNotice(name==='decide'?`Year ${c.year} company decision saved. Read the outcome below. ${[1,5,10].includes(c.year)?'Everyone now submits their written reflection on their phone.':'Continue when your team has read the outcome.'}`:name==='start'?`Year ${c.year} is open. Everyone can now submit a private recommendation on their phone.`:`Year ${next.company.year} is open. Read the briefing, then discuss your options.`);}
    catch(error) {setLocalError(error.message);setError(error.message);}
    finally {setBusy(false);}
  }
  return <Stack spacing={2} className="v4-workspace">{notice&&<Alert severity="success" role="status">{notice}</Alert>}{localError&&<Alert severity="error" role="alert">{localError}</Alert>}<Box className="participant-page-head"><Box><Typography component="h1" variant="h4">{c.flag} {c.name}</Typography><Typography>{s?`${s.calendar_year} · Year ${c.year} · ${s.title}`:'Year 9 handoff'}</Typography></Box>{c.deadline?<Timer deadline={c.deadline}/>:<Typography>{value.session.minutes>0?`Suggested discussion · ${value.session.minutes} minutes`:"Discuss at your team’s pace"}</Typography>}</Box>{c.power_announcements?.map((p,i)=><Alert key={i} severity="info">{p.announcement} · {money(p.cost)}</Alert>)}{c.annual_notice&&<Alert severity="warning">{c.annual_notice}</Alert>}{c.midpoint_warning_until&&<Alert severity="warning">The facilitator is bringing companies to Year 5. Submit your current decision before the final submission window closes.</Alert>}<Tabs value={view} onChange={(_,next)=>setView(next)} aria-label="Company tasks" variant="scrollable"><Tab value="team" label="Team QR"/><Tab value="brief" label="Current year" disabled={!c.started&&c.phase==='decision'}/><Tab value="status" label="Company status"/><Tab value="record" label="Record"/></Tabs><Box className="v4-reading" role="region" aria-label="Company workspace" tabIndex={0}>{view==='team'?<CardPages label="Team joining"><Paper variant="outlined" className="work-panel"><QR url={phoneLink(value.session.id,c.id,value.join_token)}/><Typography>Each student chooses one role on their phone.</Typography></Paper><Paper variant="outlined" className="work-panel"><Typography component="h2" variant="h6">Your team</Typography>{value.session.roles.map(role=><Typography key={role}>{role} · {c.roles_taken.includes(role)?'Joined':'Available'}</Typography>)}{!c.started&&<Typography role="status">{c.active===false?'Your company is withdrawn.':'Start with the students present. Unfilled roles do not block your team; others can join later.'}</Typography>}{!c.started&&<Button variant="contained" disabled={value.read_only||busy||c.active===false} onClick={()=>action('start')}>Start Year {c.year}</Button>}</Paper></CardPages>:view==='status'?<Paper variant="outlined" className="work-panel"><Status state={c.state} year={c.year}/></Paper>:view==='record'?<><Record company={c}/><ReportButtons path={`${companyPath()}/report.pdf`}/></>:c.phase==='handoff'?<Alert severity="info">Years 1–8 are complete. Your company’s state and obligations are retained. The Year 9 scenario is awaiting its specification.</Alert>:['checkpoint','final_checkpoint','complete'].includes(c.phase)?<Stack spacing={2}><Typography component="h2" variant="h5">Year {c.year} Complete</Typography><Typography>Your company has completed this industry review.</Typography><Typography>Executive reflections submitted: {progress.reflections} of {progress.active}</Typography><Typography>{(c.year===10?c.final_ready:c.checkpoint_ready)?c.year===5?'Your work is saved. Your teacher will release Year 6 after the class discussion.':'Your work is saved. Your teacher will reveal the final results. Your report is available from Record.':'Waiting for all active team members to finish their phone reflections.'}</Typography></Stack>:c.external_announcement&&!externalSeen?<Stack spacing={2}><CardPages label="Industry announcement"><Paper variant="outlined" className="work-panel"><Stack direction="row" spacing={3} alignItems="center"><BrandMark name="vfi"/><BrandMark name="facepass"/></Stack><Typography component="h2" variant="h6">{c.external_announcement.title}</Typography><Paragraphs text={c.external_announcement.text}/></Paper><Paper variant="outlined" className="work-panel"><Typography component="h2" variant="h6">{c.external_announcement.public_response_title||s.title}</Typography><Paragraphs text={c.external_announcement.public_response||s.story}/></Paper></CardPages><Button variant="contained" onClick={()=>setExternalSeen(true)}>Read your company’s decision</Button></Stack>:c.phase==='decision'?<CardPages label="Annual decision"><Paper variant="outlined" className="work-panel"><Stack spacing={2}>{c.year===1&&<Stack direction="row" spacing={2} alignItems="center"><BrandMark name="fairpass"/><Typography>Technology offered by VFI</Typography></Stack>}<Paragraphs text={s.supplier_context||''}/><Paragraphs text={s.story}/><Typography component="h2" variant="h6">{s.question}</Typography><Typography>Cash reserves {money(c.state.cash)}</Typography><Typography variant="body2">Conventional ticketing means selling tickets through your existing service without FairPass identity verification. Immediate expenditure is the cash spent on this decision; annual operating fees and contract revenue are separate.</Typography><Typography role="status">Private recommendations submitted · {progress.preferences} of {progress.active}</Typography></Stack></Paper><Paper variant="outlined" className="work-panel"><RadioGroup value={choice} onChange={e=>setChoice(e.target.value)} aria-label={s.question}>{s.options.map(option=><FormControlLabel key={option.id} value={option.id} disabled={value.read_only||!c.started||option.unavailable} control={<Radio/>} label={<Box sx={{py:1}}><Typography fontWeight={700}>{option.title}</Typography><Typography>{option.detail}</Typography><Typography>Immediate expenditure · {money(option.cost)}</Typography>{option.unavailable&&<Typography>{option.blocked_by?'Blocked by '+option.blocked_by.toUpperCase():'Unaffordable'}</Typography>}</Box>}/>)}</RadioGroup><Typography id="company-submit-reason" role="status">{submissionReason}</Typography><Button variant="contained" aria-describedby="company-submit-reason" disabled={value.read_only||!!submissionReason} onClick={()=>action('decide')}>Submit company decision</Button></Paper></CardPages>:<Stack spacing={2}><Paper variant="outlined" className="work-panel"><Typography component="h2" variant="h6">Company decision · {s?.options.find(o=>o.id===decision?.option)?.title||decision?.option?.replaceAll('_',' ')}</Typography><Paragraphs text={c.history.at(-1)?.outcome}/></Paper>{c.history.at(-1)?.external_resolution&&<Paper variant="outlined" className="work-panel"><Typography component="h2" variant="h6">{c.history.at(-1).external_resolution.title}</Typography><Paragraphs text={c.history.at(-1).external_resolution.text}/></Paper>}{c.history.at(-1)?.modifiers?.map((text,index)=><Paper key={index} variant="outlined" className="work-panel"><Paragraphs text={text}/></Paper>)}{['external','internal'].map(kind=><Paper key={kind} variant="outlined" className="work-panel"><Typography component="h2" variant="h6">{kind==='external'?'External event':'Internal event'} · {c.history.at(-1)?.[kind].title}</Typography><Paragraphs text={c.history.at(-1)?.[kind].text}/>{c.history.at(-1)?.[kind].public_response&&<Paragraphs text={c.history.at(-1)[kind].public_response}/>}</Paper>)}<Typography role="status">Recommendations · {progress.preferences}/{progress.active}{progress.reflection_required&&` · Reflections · ${progress.reflections}/${progress.active}`}</Typography><Button variant="contained" disabled={busy||progress.reflection_required&&progress.reflections<progress.active} onClick={()=>action('advance')}>{progress.reflection_required&&progress.reflections<progress.active?`Waiting for ${progress.active-progress.reflections} reflections`:`Continue to Year ${Math.min(10,c.year+1)}`}</Button></Stack>}</Box></Stack>;
}

const missionTerms={
 ceo:[['Financial viability','Can the company pay its bills and keep its services running?'],['Market position','Can it retain customers and win business from promoters and venues?'],['Organizational stability','Can its staff and systems deliver the service without unresolved disruption?'],['Industry commitments','Do its actual practices support fair access, responsible technology, environmental sustainability and fair working conditions?']],
 cfo:[['Cash reserves','Money available to pay costs now. Revenue is income from services; it is not the same as cash available.'],['Financial distress','The company cannot cover a required cost. Any unpaid amount remains a bill it owes.']],
 cto:[['Technical independence','How much control the company retains over the technology it needs to operate.'],['Supplier dependence','How much it relies on another company for that technology, support and contract terms.']],
 marketing:[['Customer trust','How customers regard the company’s service and conduct.'],['Market position','Its ability to retain customers and compete for business.']],
 legal:[['Legal exposure','Unresolved legal or regulatory problems that can lead to claims, restrictions or penalties.'],['Outstanding obligations','Issues the company still needs to investigate, correct or respond to.']],
 employee:[['Involuntary layoffs','Employees losing their jobs through company decisions rather than choosing to leave.'],['Working conditions','The recorded conditions employees work under, including pressure and disruption.']],
 sustainability:[['Environmental impact','The resource use and environmental consequences of the services and technology the company adopts.']],
 relations:[['Partnership standing','The strength of relationships with artists, promoters and venues.'],['Commercial dependency','How much the company relies on particular partners for its business.']]
};
function MissionTerms({role}){return <Paper variant="outlined" className="mission-terms"><Typography component="h3" variant="subtitle1">{role==='ceo'?'What the four objectives mean':'What these terms mean'}</Typography><Box component="dl">{(missionTerms[role]||[]).map(([term,definition])=><React.Fragment key={term}><Typography component="dt" fontWeight={700}>{term}</Typography><Typography component="dd" sx={{m:0,mb:1.5}}>{definition}</Typography></React.Fragment>)}</Box>{role==='ceo'&&<Typography variant="body2">These explain the four priorities. Numerical board targets have not been supplied in the default session configuration; this briefing does not invent pass thresholds.</Typography>}</Paper>;}
const powerAction=role=>role==='ceo'?'Submit CEO override':role==='cfo'?'Block this expenditure':role==='cto'?'Veto this technical option':'Activate this intervention';

export function V4Student({value,api,companyPath,setValue,setError,ReportButtons}) {
  const [view,setView]=useState('mission'),[choice,setChoice]=useState(''),[powerChoice,setPowerChoice]=useState(''),[reflection,setReflection]=useState(''),[responsibility,setResponsibility]=useState(''),[busy,setBusy]=useState(false),[reason,setReason]=useState(''),[saved,setSaved]=useState(''),[confirmPower,setConfirmPower]=useState(false),[powerAcknowledged,setPowerAcknowledged]=useState(false),[localError,setLocalError]=useState('');
  const c=value.company,role=value.role,year=String(c.year),options=c.scenario?.options||[],recommendation=value.preferences[year];
  const draftKey=`${value.read_only?'teacher-preview':'fairpass-v4-reflection'}:${value.session.id}:${c.id}:${role.id}:${year}`;
  useEffect(()=>{setChoice(recommendation||'');setPowerChoice('');setReflection(localStorage.getItem(draftKey)??(year==='10'?value.closing_reflection?.reconsider:value.reflections[year])??'');setResponsibility(localStorage.getItem(draftKey+':responsibility')??value.closing_reflection?.responsibility??'');setSaved('');},[year]);
  async function action(name,extra={}) {
    if(value.read_only)return;
    setBusy(true);setLocalError('');setSaved('');
    try {const result=await api(`${companyPath()}/actions`,{action:name,year:c.year,option:name==='power'?powerChoice:choice,text:reflection,reconsider:reflection,responsibility,reason,...extra});setValue(result);
      setSaved(name==='preference'?`Year ${c.year} recommendation saved privately. Discuss it with your team. The company laptop submits the final decision.`:name==='reflection'?`Year ${c.year} reflection saved to the session. ${c.year===5?'Wait for your teacher to open Year 6.':c.year===10?'Your work is complete. You can download your report below.':'Your team can continue on the company laptop once everyone has submitted.'}`:name==='undo_power'?'Power activation undone. Your one use is available again; your recommendation is unchanged.':`${role.power} activated. ${['cfo','cto'].includes(role.id)?'Only the selected option is blocked. Your company can choose another option.':role.id==='ceo'?'Your selected option is now the company decision.':'Your team can continue its decision.'}`);
      if(name==='reflection'){localStorage.removeItem(draftKey);localStorage.removeItem(draftKey+':responsibility');}
    }
    catch(error) {setLocalError(error.message);setError(error.message);}
    finally {setBusy(false);}
  }
  const closed=c.phase!=='decision',final=value.session.final_revealed,waiting=!c.started&&c.phase==='decision'||c.active===false;
  const recommendationBlock=recommendationReason({busy,active:value.participant.active,closed,recommendation,choice,started:c.started,companyActive:c.active!==false});
  const reflectionBlock=reflectionReason({busy,final,year,finalReady:c.final_ready,phase:c.phase,text:reflection,responsibility,companyActive:c.active!==false});
  const reflected=year==='10'?!!value.closing_reflection:!!value.reflections[year];
  return <Box className="v4-phone">
    {saved&&<Alert severity="success" role="status" aria-live="polite">{saved}</Alert>}{localError&&<Alert severity="error" role="alert">{localError}</Alert>}<Box className="student-identity"><Typography component="h1" variant="h5">{role.title}</Typography><Typography>{c.flag} {c.name} · Year {c.year}</Typography></Box><Button className="student-report-link" variant="text" onClick={()=>setView('report')}>Open your report / PDF</Button>{waiting&&<Alert severity="info">{c.active===false?'Your company is withdrawn. Ask your teacher to restore it.':'Your company has not started yet. You can read your mission; recommendations and powers open when the company laptop starts the year from Team QR.'}</Alert>}
    <Box className="v4-reading" role="region" aria-label="Your role information" tabIndex={0}><Stack spacing={2}>
      {view==='mission'?<><Typography component="h2" variant="h6">{role.mission_title}</Typography><Paper variant="outlined" className="work-panel"><Typography component="h3" variant="subtitle1">Your priority</Typography><Typography>{role.mission}</Typography></Paper><MissionTerms role={role.id}/><Typography>Your teammates have different priorities. Use your confidential briefing to explain what this year’s choice means for yours. Your private recommendation may differ from the company’s decision.</Typography><Typography component="h3" variant="subtitle1">Your influence · {role.power}</Typography><Typography>{role.power_description}</Typography><Button variant="contained" onClick={()=>setView('current')}>Read your private briefing</Button></>
      :view==='current'?<>
        <Typography component="h2" variant="h6">Private intelligence</Typography><Paragraphs text={c.supplier_context||''}/><Paragraphs text={value.intelligence||''}/>
        <Typography component="h2" variant="h6">Your private recommendation</Typography><Typography>Read the briefing, choose what you recommend, then submit below. This records your own view; your team makes its final choice on the company laptop.</Typography>
        <RadioGroup className="student-option-list" value={recommendation||choice} onChange={e=>setChoice(e.target.value)} aria-label="Your recommendation">{options.map((option,index)=><FormControlLabel key={option.id} disabled={value.read_only||!!recommendation||closed||waiting||!value.participant.active} control={<Radio/>} value={option.id} label={<Box><Typography fontWeight={700}>{/^[A-D]\./.test(option.title)?option.title:`${String.fromCharCode(65+index)}. ${option.title}`}</Typography><Typography variant="body2">{option.detail}</Typography></Box>}/>)}</RadioGroup>
        <Typography>Your recommendation is private. Your company may choose differently.</Typography>
        <Typography id="recommendation-submit-reason" role="status">{recommendationBlock}</Typography><Button variant="contained" aria-describedby="recommendation-submit-reason" disabled={value.read_only||!!recommendationBlock} onClick={()=>action('preference')}>{recommendation?'Recommendation submitted':'Submit recommendation'}</Button>
        {!recommendation&&closed&&<Typography>Recommendation not submitted before the decision was locked.</Typography>}
        {closed&&<><Typography component="h2" variant="h6">Company decision</Typography><Typography>{value.individual_history?.at(-1)?.company_option}</Typography><Typography>{value.private_consequence}</Typography>{[1,5,10].includes(c.year)&&<Button variant="outlined" onClick={()=>setView('notes')}>{reflected?'View your reflection':'Write your reflection'}</Button>}</>}
      </>
      :view==='notes'?<>
        {value.reflection_prompt?<><Typography component="h2" variant="h6">{year==='10'?'Your Ten Years':`Year ${c.year} reflection`}</Typography>
        {year==='10'?<>
          <Paragraphs text={value.closing_intro}/>
          <Typography id="closing-reconsider-prompt">{value.closing_questions[0]}</Typography><TextField label="Your reflection" inputProps={{'aria-labelledby':'closing-reconsider-prompt'}} value={reflection} onChange={e=>{setReflection(e.target.value);localStorage.setItem(draftKey,e.target.value);}} multiline minRows={3} helperText="Two or three sentences. Private to you and your teacher." disabled={final}/>
          <Typography id="closing-responsibility-prompt">{value.closing_questions[1]}</Typography><TextField label="Your response" inputProps={{'aria-labelledby':'closing-responsibility-prompt'}} value={responsibility} onChange={e=>{setResponsibility(e.target.value);localStorage.setItem(draftKey+':responsibility',e.target.value);}} multiline minRows={2} helperText="One or two sentences." disabled={final}/>
        </>:<><Typography>{value.reflection_prompt}</Typography><TextField label="One or two sentences" value={reflection} onChange={e=>{setReflection(e.target.value);localStorage.setItem(draftKey,e.target.value);}} multiline minRows={3} helperText="Private to you and your teacher."/></>}
        <Typography id="reflection-submit-reason" role="status">{reflectionBlock}</Typography><Button variant="contained" aria-describedby="reflection-submit-reason" disabled={value.read_only||!!reflectionBlock} onClick={()=>action('reflection')}>Submit reflection</Button>
        {reflected&&year==='10'&&<><Typography component="h2" variant="h6">Your Decade Is Complete</Typography><Typography>Your individual reflections have been recorded. Your company’s results will be revealed during the final industry review.</Typography><Typography>Reflections submitted: {c.progress.reflections} of {c.progress.active}</Typography>{c.final_ready&&<Typography>Your company is ready for the final checkpoint.</Typography>}</>}
        </>:<Typography>No written reflection is required this year.</Typography>}
        <Typography component="h2" variant="h6">Your decision log</Typography>{value.individual_history?.map(entry=><Paper key={entry.year} variant="outlined" className="work-panel"><Typography component="h3" variant="subtitle2">Year {entry.year}</Typography><Typography>Your recommendation · {entry.preferred_option}</Typography><Typography>Company decision · {entry.company_option}</Typography>{entry.ceo_override&&<Typography>The CEO used an executive override.</Typography>}<Typography>{entry.consequence}</Typography>{entry.reflection&&<Typography sx={{whiteSpace:'pre-wrap'}}>{entry.reflection}</Typography>}</Paper>)}
        <Button variant="outlined" onClick={()=>setView('report')}>View your individual report</Button>
      </>
      :view==='report'?<PersonalReport api={api} companyPath={companyPath} ReportButtons={ReportButtons}/>
      :view==='feedback'?<Feedback api={api} sessionId={value.session.id} questions={value.session.feedback_questions||[]} done={()=>setView('report')} setError={setError}/>
      :<><Paper variant="outlined" className="power-warning"><Typography className="control-label">Optional executive intervention · one use</Typography><Typography component="h2" variant="h6">{role.power}</Typography><Typography>{role.power_description}</Typography><Typography>This is separate from your private recommendation. It changes what happens for the whole company.</Typography></Paper>
        <Typography role="status">{value.power_activation?`Executive power used in Year ${value.power_activation.year}.`:'Available'}</Typography>
        {value.power_unavailable_reason&&<Typography>{value.power_unavailable_reason}</Typography>}
        {['ceo','cfo','cto','sustainability','relations'].includes(role.id)&&<TextField select label={role.id==='ceo'?'Final company decision':'Affected option'} value={powerChoice} onChange={e=>setPowerChoice(e.target.value)} disabled={value.power_used||closed||waiting}>{options.filter(o=>(role.id!=='cto'||value.technical_options.includes(o.id))&&(role.id!=='cfo'||o.cost>0)).map(o=><MenuItem disabled={role.id==='ceo'&&o.unavailable} key={o.id} value={o.id}>{o.title}</MenuItem>)}</TextField>}
        <TextField label="Your reason (optional)" value={reason} onChange={e=>setReason(e.target.value)} multiline minRows={2} disabled={value.power_used||closed||waiting}/>
        {!recommendation&&!closed&&<Typography>Submit your recommendation before activating your power.</Typography>}
        <Typography id="power-action-reason" role="status">{value.read_only?'Teacher preview: activation is disabled.':busy?'Saving your intervention. Please wait.':waiting?'Your company must be started and participating before you can use a power.':value.power_used?'Your one intervention has already been used.':closed?'This year’s company decision is already locked.':!value.participant.active?'Your teacher has marked your participation inactive.':!recommendation?'Submit your private recommendation in Briefing & vote first.':value.power_unavailable_reason||(['ceo','cfo','cto','sustainability','relations'].includes(role.id)&&!powerChoice?'Choose the affected option above before reviewing your intervention.':'Reviewing opens a confirmation. Nothing is activated yet.')}</Typography><Button aria-describedby="power-action-reason" variant="outlined" disabled={value.read_only||busy||waiting||value.power_used||!!value.power_unavailable_reason||!recommendation||closed||!value.participant.active||['ceo','cfo','cto','sustainability','relations'].includes(role.id)&&!powerChoice} onClick={()=>{setPowerAcknowledged(false);setConfirmPower(true);}}>Review intervention before activating</Button>
        {value.power_result&&<><Typography>{value.power_result.private}</Typography><Typography>Cash cost: {money(value.power_result.cost)}</Typography>{value.power_result.obligations_created.map(k=><Typography key={k}>{k.replaceAll('_',' ')}</Typography>)}</>}
      </>}
      {final&&<Box className="inline-actions"><Button onClick={()=>setView('report')}>Your final report</Button><Button onClick={()=>setView('feedback')}>Optional feedback</Button></Box>}
      {value.power_activation&&value.power_activation.year===c.year&&<Button variant="outlined" disabled={value.read_only||busy} onClick={()=>action('undo_power')}>Undo accidental power activation</Button>}
    </Stack></Box>
    <Dialog open={confirmPower} onClose={()=>setConfirmPower(false)} fullWidth><DialogTitle>Confirm intervention · {role.power}</DialogTitle><DialogContent><Stack spacing={2}><Typography>{role.power_description}</Typography>{powerChoice&&<Typography fontWeight={700}>Selected option: {options.find(o=>o.id===powerChoice)?.title}</Typography>}<Typography>{['cfo','cto'].includes(role.id)?'This blocks only the selected option. Other options remain available.':role.id==='ceo'?'This immediately submits your selected option as the final company decision.':`Cost: ${money(({marketing:.15,legal:.1,sustainability:.1,relations:.1,employee:.2})[role.id]||0)}. This uses your one executive intervention.`}</Typography><Typography>You can undo an accidental activation while the current decision is still open. A CEO override can be undone until reflections on that decision begin.</Typography><FormControlLabel className="power-acknowledgement" control={<Checkbox checked={powerAcknowledged} onChange={(_,checked)=>setPowerAcknowledged(checked)}/>} label="I intend to use my one executive intervention on this decision."/></Stack></DialogContent><DialogActions><Button onClick={()=>setConfirmPower(false)}>Cancel</Button><Button variant="contained" disabled={busy||!powerAcknowledged} onClick={()=>{setConfirmPower(false);action('power');}}>{powerAction(role.id)}</Button></DialogActions></Dialog>
    <Tabs className="student-task-navigation" value={['report','feedback'].includes(view)?false:view} onChange={(_,next)=>setView(next)} aria-label="Your role tasks" variant="fullWidth"><Tab value="mission" label="My mission"/><Tab value="current" label="Briefing & vote"/><Tab value="notes" label="Reflection"/><Tab value="power" label="My power"/></Tabs>
  </Box>;
}
function saveFile(text,type,name) {const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function PersonalReport({api,companyPath,ReportButtons}) {
 const [data,setData]=useState(null),[error,setError]=useState('');
 useEffect(()=>{api(`${companyPath()}/personal-report`).then(setData).catch(e=>setError(e.message));},[]);
 if(error)return <Alert severity="error">{error}</Alert>;
 if(!data)return <Typography role="status">Loading your report…</Typography>;
 return <><Typography component="h2" variant="h6">Your individual report</Typography><Typography>{data.name} · {data.company}</Typography><Typography>{data.power_status}</Typography><Typography>{data.mission.definition}</Typography><Typography>{data.mission.reason}</Typography><Box className="inline-actions"><ReportButtons path={`${companyPath()}/personal.pdf`}/><Button variant="outlined" onClick={()=>saveFile(data.text,'text/plain;charset=utf-8','individual-report.txt')}>Download text</Button><Button variant="outlined" onClick={()=>{const escape=t=>t.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');saveFile(`<!doctype html><html lang="en"><meta charset="utf-8"><title>Your simulation report</title><style>body{font:1rem/1.6 Arial,sans-serif;max-width:75ch;margin:2rem auto;padding:1rem}p{white-space:pre-wrap}</style><main><h1>Your simulation report</h1>${data.text.split('\n\n').map(t=>'<p>'+escape(t)+'</p>').join('')}</main></html>`,'text/html;charset=utf-8','individual-report.html');}}>Download HTML</Button></Box><Paragraphs text={data.text}/></>;
}
function Feedback({api,sessionId,questions,done,setError}) {
 const [ratings,setRatings]=useState({}),[text,setText]=useState({}),[busy,setBusy]=useState(false);
 const scale=['Strongly disagree','Disagree','Neither agree nor disagree','Agree','Strongly agree'];
 async function submit(){setBusy(true);try{await api(`/api/sessions/${sessionId}/feedback`,{ratings,text});done();}catch(e){setError(e.message);}finally{setBusy(false);}}
 return <><Typography component="h2" variant="h6">Help improve VFI simulation</Typography><Typography>Your feedback will help improve future versions of the simulation. Responses are voluntary and do not affect your assessment.</Typography>{questions.map((q,i)=>i<4?<Box key={q}><Typography id={`feedback-${i}`}>{q}</Typography><TextField select label="Your rating" fullWidth SelectProps={{labelId:`feedback-${i}`}} value={ratings[String(i+1)]||''} onChange={e=>{const next={...ratings};if(e.target.value==='')delete next[String(i+1)];else next[String(i+1)]=Number(e.target.value);setRatings(next);}}><MenuItem value="">No response</MenuItem>{scale.map((label,j)=><MenuItem key={label} value={j+1}>{label}</MenuItem>)}</TextField></Box>:<Box key={q}><Typography id={`feedback-${i}`}>{q}</Typography><TextField label="Your feedback" fullWidth inputProps={{maxLength:2000,'aria-labelledby':`feedback-${i}`}} multiline minRows={2} value={text[String(i+1)]||''} onChange={e=>setText({...text,[String(i+1)]:e.target.value})} /> </Box>)}<Button variant="contained" onClick={submit} disabled={busy}>Submit feedback</Button><Button variant="outlined" onClick={done}>Skip and open your report</Button></>;
}
export function V4Facilitator({value,api,sessionPath,setError,refresh,projection,preview,ReportButtons,QR,phoneLink,Timer}) {
  const [warningSeconds,setWarningSeconds]=useState(30),[settings,setSettings]=useState(null),[controlBusy,setControlBusy]=useState(false),[notice,setNotice]=useState(''),[controlError,setControlError]=useState(''),[move,setMove]=useState(null),[inspect,setInspect]=useState(null),[inspection,setInspection]=useState(null),[inspectRole,setInspectRole]=useState('company'),[newCompany,setNewCompany]=useState(null),[countries,setCountries]=useState([]);
  useEffect(()=>{api('/api/v4/content',undefined,'').then(c=>setCountries(c.countries)).catch(e=>setControlError(e.message));},[]);
  useEffect(()=>{if(!inspect)return;setInspection(null);let alive=true;api(`${sessionPath()}/inspect/${inspect.company}/${inspect.year}`).then(data=>{if(alive)setInspection(data);}).catch(e=>{if(alive)setControlError(e.message);});return()=>{alive=false;};},[inspect?.company,inspect?.year]);
  const activeCompanies=value.companies.filter(c=>c.active!==false);
  const allReady=activeCompanies.length>0&&activeCompanies.every(c=>c.checkpoint_ready);
  const finalReady=activeCompanies.length>0&&activeCompanies.every(c=>c.final_ready);
  async function control(action,extra={}) {
    setControlBusy(true);setControlError('');setNotice('');try {await api(`${sessionPath()}/control`,{action,...extra});await refresh();setNotice(({move:`Moved ${extra.company?'the selected company':'participating companies'} to the open Year ${extra.year} decision.`,release5:'Year 6 is now open for participating companies.',settings:'Session settings saved.',participant:'Participant status saved.',company_participation:'Company participation updated. Records retained.',undo_power:'Accidental power activation undone.',reveal5:'Year 5 class results released.',reveal10:'Final results released. Reports are available.'})[action]||'Session updated.');return true;}catch(error){setControlError(error.message);setError(error.message);return false;}finally{setControlBusy(false);}
  }
  async function download() {
    try {const data=await api(`${sessionPath()}/export`);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=value.code+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(error){setError(error.message);}
  }
  return <Stack spacing={2}><Typography component="h1" variant="h4">{value.label}</Typography>{notice&&<Alert severity="success" role="status">{notice}</Alert>}{controlError&&<Alert severity="error" role="alert">{controlError}</Alert>}<Box className="inline-actions"><Button variant="contained" component="a" href={projection()} target="_blank" rel="noreferrer">Show joining screen</Button><Button component="a" href="/media/vfi/intro.mp4" target="_blank" rel="noreferrer" variant="outlined">Open introduction video</Button><Button component="a" href="/media/vfi/smile-and-pass.mp4" target="_blank" rel="noreferrer" variant="outlined">Open Year 5 video</Button><Button component="a" href="/media/vfi/year-10.mp4" target="_blank" rel="noreferrer" variant="outlined">Open Year 10 video</Button><Button component="a" href={preview(5)} target="_blank" rel="noreferrer">Preview Year 5</Button><Button component="a" href={preview(10)} target="_blank" rel="noreferrer">Preview Year 10</Button><Button variant="contained" disabled={controlBusy||value.complete} onClick={()=>setNewCompany({name:'',country:'Sweden'})}>Add company</Button><Button variant="outlined" disabled={value.complete} onClick={()=>setSettings({active_years:[...value.active_years],minutes:value.minutes,checkpoint_minute:value.checkpoint_minute,end_minute:value.end_minute,registration_open:value.registration_open!==false})}>Session settings</Button><Button variant="outlined" onClick={()=>control(value.paused?'resume':'pause')}>{value.paused?'Resume':'Pause'}</Button><Button variant="outlined" onClick={download}>Download JSON</Button><Button variant="outlined" onClick={()=>{if(window.confirm("Reset this session? The current run will be retained in the session export history."))control('reset');}}>Reset session</Button></Box><Box className="inline-actions"><Button variant="contained" disabled={controlBusy||value.complete} onClick={()=>setMove({year:10,company:null})}>Move everyone to an open decision</Button><TextField label="Countdown before automatic defaults (seconds)" helperText="Closing decisions includes Year 10. To let teams decide Year 10, use Move to an open decision." type="number" value={warningSeconds} onChange={e=>setWarningSeconds(Number(e.target.value))} inputProps={{min:0,max:300}}/><Button variant="contained" disabled={value.released5||value.complete} onClick={()=>control('midpoint',{warning_seconds:warningSeconds})}>Bring companies to Year 5</Button><Button variant="outlined" disabled={!allReady} onClick={()=>control('reveal5')}>Show Year 5 class results</Button><Button variant="contained" disabled={controlBusy||!allReady||value.released5} onClick={()=>control('release5')}>Open Year 6 for everyone</Button>{!value.released5&&!allReady&&<Typography role="status">Year 6 opens when participating companies have finished Year 5 decisions and reflections. Withdraw an empty company if it is blocking the class.</Typography>}<Button component="a" href={preview(5)} target="_blank" rel="noreferrer" variant="outlined">Year 5 video and results</Button><Button component="a" href={projection()} target="_blank" rel="noreferrer" variant="outlined">Open class projection</Button><Button variant="contained" disabled={!value.released5||value.complete||value.final_requested} onClick={()=>control('final',{warning_seconds:warningSeconds})}>Close remaining decisions after countdown</Button><Button variant="outlined" disabled={!finalReady||value.final_revealed} onClick={()=>control('reveal10')}>Release final industry results</Button><Button variant="outlined" disabled={!value.final_revealed} onClick={()=>control('debrief')}>Show debrief</Button></Box><ReportButtons path={`${sessionPath()}/logs.pdf`} downloadOnly/><Typography role="status">{value.workshop_started&&`Elapsed ${Math.floor((Date.now()/1000-value.workshop_started)/60)} min · `}Discussion estimate {value.minutes} min · checkpoint target {value.checkpoint_minute} min · finish target {value.end_minute} min</Typography><Typography>Session {value.code} · Password {value.password}</Typography><Typography>{value.complete?'Simulation complete. Decisions and outcomes are locked; reports and voluntary feedback remain available.':'Each active student recommends before the company decides. Written reflections are required in Years 1, 5 and 10.'}</Typography><Box className="v4-reading" role="region" aria-label="Company progress" tabIndex={0}>{value.companies.map(c=><Paper key={c.id} variant="outlined" className="work-panel"><Typography component="h2" variant="h6">{c.flag} {c.name} · Year {c.year}</Typography><Typography>{c.active===false?'Withdrawn · records retained':({decision:'Decision open',event:'Decision saved · read outcome and complete any reflections',checkpoint:'Year 5 complete · waiting for teacher to open Year 6',final_checkpoint:'Closing reflections complete · ready for results',complete:'Complete · reports available'})[c.phase]||c.phase} · recommendations {c.progress.preferences}/{c.progress.active} · reflections {c.progress.reflections}/{c.progress.active}</Typography><Button variant="outlined" onClick={()=>{setInspectRole('company');setInspect({company:c.id,year:c.year});}}>See this team’s briefing and options</Button><Button variant="outlined" disabled={controlBusy||value.complete||c.active===false} onClick={()=>setMove({company:c.id,year:Math.min(10,c.year+1)})}>Move this team</Button><ReportButtons path={`${sessionPath()}/companies/${c.id}/report.pdf`} name={`${value.code}-${c.name.replace(/[^a-z0-9]/gi,'-')}.pdf`} downloadOnly/><Button variant="outlined" disabled={controlBusy||value.complete} onClick={()=>control('company_participation',{company:c.id,active:c.active===false})}>{c.active===false?'Restore company':'Remove from session'}</Button>{c.year===5&&c.phase==='decision'&&<Button variant="outlined" onClick={()=>control('expire5',{company:c.id})}>Apply expired Year 5 default</Button>}{c.year===10&&<Typography>{c.final_ready?'Ready for the final checkpoint':'Waiting for closing reflections'}</Typography>}{c.participants.filter(member=>member.power_used).map(member=><Button key={`undo-${member.role}`} variant="outlined" disabled={controlBusy||value.complete} onClick={()=>control('undo_power',{company:c.id,role:member.role})}>Undo {member.role.toUpperCase()} power</Button>)}<Typography variant="body2">Only checked students are required for recommendations and reflections. Uncheck anyone absent or disconnected; their saved work is retained.</Typography>{c.participants.map(member=><FormControlLabel key={member.role} control={<Checkbox disabled={value.complete} checked={member.active} onChange={()=>control('participant',{company:c.id,role:member.role,active:!member.active})}/>} label={`${member.name} · ${member.role} · ${member.active?'Active':'Inactive'}`}/>)}</Paper>)}</Box><Dialog open={!!settings} onClose={()=>!controlBusy&&setSettings(null)} fullWidth><DialogTitle>Session settings</DialogTitle><DialogContent>{settings&&<Stack spacing={2} sx={{pt:1}}><Typography>Completed decisions stay recorded. Unselected unresolved years use the agreed defaults. Written reflections remain at Years 1, 5 and 10.</Typography><Box className="inline-actions">{[['minutes','Discussion estimate (min)'],['checkpoint_minute','Checkpoint target (min)'],['end_minute','Finish target (min)']].map(([key,label])=><TextField key={key} type="number" label={label} value={settings[key]} onChange={e=>setSettings({...settings,[key]:Number(e.target.value)})}/>)}</Box><Box component="fieldset"><Typography component="legend">Years requiring a company decision</Typography>{Array.from({length:10},(_,i)=>i+1).map(year=><FormControlLabel key={year} control={<Checkbox checked={settings.active_years.includes(year)} onChange={(_,checked)=>setSettings({...settings,active_years:checked?[...settings.active_years,year].sort((a,b)=>a-b):settings.active_years.filter(y=>y!==year)})}/>} label={`Year ${year}`}/>)}</Box><FormControlLabel control={<Checkbox checked={settings.registration_open} onChange={(_,checked)=>setSettings({...settings,registration_open:checked})}/>} label="Allow new companies to join"/><Typography>Existing companies can still return while new registration is closed.</Typography></Stack>}</DialogContent><DialogActions><Button disabled={controlBusy} onClick={()=>setSettings(null)}>Cancel</Button><Button variant="contained" disabled={controlBusy} onClick={async()=>{if(await control('settings',settings))setSettings(null);}}>Save changes</Button></DialogActions></Dialog>
    <Dialog open={!!newCompany} onClose={()=>!controlBusy&&setNewCompany(null)} fullWidth><DialogTitle>Add company</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><TextField label="Company name" value={newCompany?.name||''} onChange={e=>setNewCompany({...newCompany,name:e.target.value})}/><TextField select label="EU headquarters" value={newCompany?.country||'Sweden'} onChange={e=>setNewCompany({...newCompany,country:e.target.value})}>{countries.map(country=><MenuItem key={country} value={country}>{country}</MenuItem>)}</TextField><Typography>The company starts in Year 1 with no minimum team size. It can join even when student registration is closed. Students can find it using its name and the session password.</Typography></Stack></DialogContent><DialogActions><Button disabled={controlBusy} onClick={()=>setNewCompany(null)}>Cancel</Button><Button variant="contained" disabled={controlBusy||!newCompany?.name.trim()} onClick={async()=>{setControlBusy(true);setControlError('');try{const added=await api(`${sessionPath()}/companies`,newCompany);await refresh();setNotice(added.resumed?'Existing company reopened. Records retained.':'Company added. Students can join by company name.');setNewCompany(null);}catch(e){setControlError(e.message);}finally{setControlBusy(false);}}}>Add company</Button></DialogActions></Dialog>
    <Dialog open={!!move} onClose={()=>!controlBusy&&setMove(null)} fullWidth><DialogTitle>Move {move?.company?'this team':'participating teams'} to an open decision</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><TextField select label="Decision year" value={move?.year||10} onChange={e=>setMove({...move,year:Number(e.target.value)})}>{Array.from({length:10},(_,i)=>i+1).map(y=><MenuItem key={y} value={y}>Year {y}</MenuItem>)}</TextField><Typography>Earlier unanswered decisions receive the agreed defaults. Existing decisions, recommendations and reflections stay recorded. The selected year stays OPEN for students to recommend and the company to decide.</Typography><Typography>Teams cannot move backwards. Moving beyond Year 5 requires its decision and reflections to be complete.</Typography></Stack></DialogContent><DialogActions><Button disabled={controlBusy} onClick={()=>setMove(null)}>Cancel</Button><Button variant="contained" disabled={controlBusy} onClick={async()=>{if(await control('move',move))setMove(null);}}>Apply earlier defaults and open Year {move?.year}</Button></DialogActions></Dialog>
    <Dialog open={!!inspect} onClose={()=>setInspect(null)} fullWidth maxWidth="md"><DialogTitle>Team briefing · read only</DialogTitle><DialogContent><Stack spacing={2} sx={{pt:1}}><Box className="inline-actions"><TextField select label="Year" value={inspect?.year||1} onChange={e=>setInspect({...inspect,year:Number(e.target.value)})}>{Array.from({length:10},(_,i)=>i+1).map(y=><MenuItem key={y} value={y}>Year {y}</MenuItem>)}</TextField><TextField select label="View" value={inspectRole} onChange={e=>setInspectRole(e.target.value)}><MenuItem value="company">Company laptop</MenuItem>{Object.entries(inspection?.roles||{}).map(([key,r])=><MenuItem key={key} value={key}>{r.title} · private phone briefing</MenuItem>)}</TextField></Box>{!inspection?<Typography role="status">Loading briefing…</Typography>:<><Typography component="h2" variant="h6">{inspection.scenario.title}</Typography><Paragraphs text={inspection.scenario.story}/>{inspectRole!=='company'&&<><Typography fontWeight={700}>Private mission</Typography><Paragraphs text={inspection.roles[inspectRole]?.mission}/><Paragraphs text={inspection.roles[inspectRole]?.intelligence}/></>}<Typography component="h3" variant="subtitle1">{inspection.scenario.question}</Typography>{inspection.company.scenario.options.map(o=><Paper variant="outlined" className="work-panel" key={o.id}><Typography fontWeight={700}>{o.title}</Typography><Typography>{o.detail}</Typography><Typography>Immediate expenditure · {money(o.cost)}{o.unavailable?' · unavailable on entering this year':''}</Typography></Paper>)}<Typography>Recorded choice: {inspection.recorded_decision?.option||'No decision recorded'}. Viewing this does not move the team or change its work.</Typography><Alert severity="info">Actual screen preview · read only. Tabs work; submission and download actions are disabled.</Alert><Box sx={{maxWidth:inspectRole==='company'?'100%':'28rem',mx:'auto',width:'100%',minHeight:'30rem'}}><Box >{inspectRole==='company'?<V4Company key={`company-${inspect.year}`} value={inspection.company_view} api={async()=>{throw Error('Read-only preview');}} companyPath={()=>`${sessionPath()}/companies/${inspect.company}`} setValue={()=>{}} setError={()=>{}} QR={QR} phoneLink={phoneLink} ReportButtons={()=>null} Timer={Timer}/>:inspection.views[inspectRole]?<V4Student key={`${inspectRole}-${inspect.year}`} value={inspection.views[inspectRole]} api={async()=>{throw Error('Reports are available outside this read-only preview.');}} companyPath={()=>`${sessionPath()}/companies/${inspect.company}`} setValue={()=>{}} setError={()=>{}} ReportButtons={()=>null}/>:<Typography>This role has not joined this team.</Typography>}</Box></Box></>}</Stack></DialogContent><DialogActions><Button onClick={()=>setInspect(null)}>Close briefing</Button></DialogActions></Dialog>
    </Stack>;
}

export function V4Industry({value}) {
 const final=value.final_revealed;
 // Video presentation never gates or replaces released results.
 if(value.platform_presentation==='commercial')return <Stack spacing={3}><Stack direction="row" spacing={3} sx={{flexWrap:'wrap'}}><BrandMark name="vfi" height={72}/><BrandMark name="facepass" height={72}/></Stack><Typography component="h1" variant="h4">Smile and Pass</Typography>{value.platform_commercial.video_src?<Box component="video" controls playsInline preload="metadata" src={value.platform_commercial.video_src} sx={{width:'100%',maxHeight:'65dvh'}} aria-label="VFI Smile and Pass commercial"/>:<Typography>The lecturer presents the VFI commercial.</Typography>}<Typography component="h2" variant="h6">Closing voiceover</Typography><Paragraphs text={value.platform_commercial.transcript}/><Typography sx={{whiteSpace:'pre-line'}}>{value.platform_commercial.closing_screen}</Typography></Stack>;
 if(value.platform_presentation==='announcement')return <Stack spacing={3}><Typography component="h1" variant="h4">{value.platform_announcement.title}</Typography><Paragraphs text={value.platform_announcement.text}/></Stack>;
 const metrics=[['reported_annual_revenue','Revenue position (€M)'],['cash','Cash (€M)'],['customer_trust','Customer trust'],['workforce_conditions','Workforce conditions'],['technical_reliability','Technical reliability'],['sustainability','Sustainability'],['partnership_standing','Partnerships']];
 if(value.debrief_visible)return <Stack spacing={3}><Typography component="h1" variant="h4">What Did We Learn?</Typography>{value.debrief_questions.map((q,i)=><Paper key={q} variant="outlined" className="work-panel"><Typography component="h2" variant="h6">{['The decisions','The people','The organization','The business case'][i]}</Typography><Typography>{q}</Typography></Paper>)}<Paragraphs text={value.debrief_statement?.replace('Display:\n\n','').replaceAll('"','').replace(/\n---$/,'')||''}/></Stack>;
 return <Stack spacing={3}>
 <Typography component="h1" variant="h4">{final?'Ten Years Later: The State of the Industry':'Five Years Later: The State of the Industry'}</Typography>
 <Paragraphs text={value.checkpoint_text?.announcement||''}/><Typography>Reported annual revenue is the commercial-scale comparison. Equal values share a rank.</Typography>
 <TableContainer tabIndex={0} role="region" aria-label="Industry checkpoint"><Table><TableHead><TableRow><TableCell>Company</TableCell>{metrics.map(([key,label])=><TableCell key={key}>{label}</TableCell>)}</TableRow></TableHead><TableBody>{value.comparison.map(row=><TableRow key={row.id}><TableCell component="th" scope="row">{row.flag} {row.name}</TableCell>{metrics.map(([key])=><TableCell key={key}>{row.state[key]} · rank {row.ranks[key]??'—'}</TableCell>)}</TableRow>)}</TableBody></Table></TableContainer>
 {value.comparison.map(row=><Paper component="section" key={row.id} variant="outlined" className="work-panel"><Stack spacing={2}>
 <Typography component="h2" variant="h6">{row.flag} {row.name}</Typography><Typography>Technology strategy · {row.state.procurement}</Typography><Typography>Verification provider · {row.state.identity_technology_provider?.replaceAll('_',' ')||'Not recorded'} · VFI supplier contract · {row.state.vfi_supplier_contract?'Yes':'No'}</Typography><Typography>FacePass contract · {row.state.facepass_contract||'Not recorded'} · supplier data terms · {row.state.supplier_data_rights?.replaceAll('_',' ')||'Not recorded'} · Facial entry · {row.state.facial_entry_operational?'Operational':'Not operational'}</Typography><Typography>Strategic direction · {row.state.strategic_direction?.replaceAll('_',' ')||'Not yet selected'}</Typography><Typography>Employees · {row.state.employees}</Typography><Typography>Northstar · {row.state.northstar_contract}</Typography><Typography>Venue entry · {row.state.biometric_venue_contract_active?'Biometric contract active':row.state.entry_contract_active?'Nonbiometric contract active':'Not active'} · Meridian · {row.state.commercial_partnership_active?'Active':'Not active'} · Independent programme · {row.state.independent_programme_active?'Active':'Not active'}</Typography><Typography>Reporting choice · {row.state.reporting_choice?.replaceAll('_',' ')||'Not yet selected'}</Typography><Typography>Outstanding obligations · {row.obligations?.map(k=>k.replaceAll('_',' ')).join(', ')||'None recorded'}</Typography>
 {final&&<>
 <Typography component="h3" variant="subtitle1">Year 5 to Year 10</Typography><TableContainer tabIndex={0} role="region" aria-label={`${row.name} checkpoint comparison`}><Table size="small"><TableHead><TableRow><TableCell>Indicator</TableCell><TableCell>Year 5</TableCell><TableCell>Year 10</TableCell><TableCell>Change</TableCell></TableRow></TableHead><TableBody>{Object.entries(row.comparison).map(([key,v])=><TableRow key={key}><TableCell component="th" scope="row">{key.replaceAll('_',' ')}</TableCell><TableCell>{v.year5??'Unavailable'}</TableCell><TableCell>{v.year10}</TableCell><TableCell>{v.change??'Unavailable'}</TableCell></TableRow>)}</TableBody></Table></TableContainer>
 <Typography component="h3" variant="subtitle1">Industry commitments</Typography>
 <Typography>Fair access · Trust {row.state.customer_trust}; human assistance {row.state.human_assistance_capacity}; support readiness {row.state.customer_support_readiness}; transfers {row.state.ticket_transfers?'available':'not introduced'}; reservations {row.state.payday_reservations?'available':'not introduced'}.</Typography>
 <Typography>Responsible technology · Reliability {row.state.technical_reliability}; assurance evidence {row.state.assurance_evidence}; facial entry {row.state.facial_entry_operational?'operational':'not operational'}; law-enforcement request {row.state.law_enforcement_request_resolved?'resolved under the narrowed order':'not resolved'}.</Typography>
 <Typography>Environmental sustainability · Recorded sustainability indicator {row.state.sustainability}; technology {row.state.procurement}; impact assessment {row.state.sustainability_assessment_used?'conducted':'not commissioned'}.</Typography>
 <Typography>Fair working conditions · {row.state.employees} employees; conditions {row.state.workforce_conditions}; workforce pressure {row.state.workforce_pressure}; labour dispute risk {row.state.labour_dispute_risk}; involuntary layoffs {row.state.involuntary_layoffs}.</Typography>
 <Typography>Economic viability · Revenue {money(row.state.reported_annual_revenue)}; cash {money(row.state.cash)}; unpaid VFI costs {money(row.state.vfi_operating_payable_m)}; commercial dependency {row.state.commercial_dependency}; financial distress {row.state.financial_distress?'recorded':'not recorded'}.</Typography>
 <Typography component="h3" variant="subtitle1">Company history</Typography>{row.history.map(step=><Typography key={step.year}>Year {step.year} · {step.option_title||step.option.replaceAll('_',' ')} · {step.decision_source.replaceAll('_',' ')}{step.resolution_mode==='financial_fallback'?' · financial fallback':''}</Typography>)}
 <Typography component="h3" variant="subtitle1">Documented stakeholder consequences</Typography>{row.human_consequences.map((text,i)=><Typography key={i}>{text}</Typography>)}
 </>}
 </Stack></Paper>)}
 {!final&&<><Typography component="h2" variant="h6">Industry commitments</Typography>{Object.entries(value.checkpoint_text?.commitments||{}).map(([title,text])=><Box key={title}><Typography component="h3" variant="subtitle2">{title}</Typography><Paragraphs text={text}/></Box>)}</>}
 </Stack>;
}
